        assertNotNull(result);
        assertEquals(BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN, result.getType());
        assertEquals(-1, result.getWriteLimit());
        assertFalse(result.isThrowOnWriteLimitReached());
    }

    @Test
