        BasicContentHandlerFactory result = BasicContentHandlerFactory.newInstance(BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN, parseContext);
        assertFalse(result.isThrowOnWriteLimitReached());
    }
}
